    tfType: 'google_compute_ssl_policy',
    className: 'GoogleComputeSslPolicy',
    barrel: 'compute',
    kind: CatalogKind.resource,
    summary:
        'Factory wrapper for `google_compute_ssl_policy` (provider `hashicorp/google ~> 7.0`).',
    constructorParams: <String>[
