    tfType: 'google_compute_subnetwork_iam_member',
    className: 'GoogleComputeSubnetworkIamMember',
    barrel: 'compute',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_compute_subnetwork_iam_member`.',
    constructorParams: <String>[
