    className: 'GoogleFirebaseAppHostingBuild',
    barrel: 'firebase_app_hosting',
    kind: CatalogKind.resource,
    summary:
        'Factory wrapper for `google_firebase_app_hosting_build` (provider `hashicorp/google ~> 7.0`).',
    constructorParams: <String>[
